select count(distinct org_id) as clients_2024
from read_parquet('data/payments.parquet')
where paid_at >= date '2024-01-01'
  and paid_at <  date '2025-01-01'
  and recorded_at <= date '2025-10-01';

select count(distinct org_id) as clients_2024
from read_parquet('data/payments.parquet')
where paid_at >= date '2024-01-01'
  and paid_at <  date '2025-01-01'
  and recorded_at <= date '2025-10-01';

-- план по клиентам и выручке за 2024, по сегментам
select size_segment, units_plan, revenue_plan_model, revenue_plan_premium,
       revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
where plan_year = 2024
order by size_segment;

-- распределение size_segment в orgs, включая NULL
select size_segment, count(*) 
from read_parquet('data/orgs.parquet')
group by 1;

select plan_year, size_segment, units_plan, revision_date
from read_parquet('data/plan.parquet')
order by plan_year, size_segment, revision_date

select
  min(paid_at), max(paid_at), min(recorded_at), max(recorded_at)
from read_parquet('data/payments.parquet')

-- 1. Простой способ: суммарная длительность подписок на организацию (по всем seq_no), без учёта цензурирования
select
  avg(total_months) as avg_lifetime_months_simple,
  avg(total_months)/12.0 as avg_lifetime_years_simple,
  count(*) as n_orgs
from (
  select org_id, sum(duration_months) as total_months
  from read_parquet('data/subscriptions.parquet')
  group by org_id
) t

-- 2. Проверим долю организаций, у которых подписка ещё активна (не закончилась) на дату курсора -
-- это цензурированные наблюдения, которые "портят" простой способ (2)
select
  count(*) as total_orgs,
  sum(case when max_end_date > date '2025-10-01' or max_end_date is null then 1 else 0 end) as still_active_orgs
from (
  select org_id, max(end_date) as max_end_date
  from read_parquet('data/subscriptions.parquet')
  group by org_id
) t

-- метод "наивное среднее" по всем подпискам (включая ещё не закрытые/цензурированные)
SELECT avg(duration_months)/12.0 AS naive_avg_years
FROM subscriptions;

-- метод "все организации, включая активные" — срок жизни до курсора (2025-10-01) для тех, кто не ликвидирован
SELECT avg(
  date_diff('month', registered_at,
    coalesce(liquidated_at, DATE '2025-10-01'))
)/12.0 AS all_orgs_incl_active_years
FROM orgs;

SELECT avg(
  date_diff('month', registered_at,
    coalesce(liquidated_at, DATE '2025-10-01'))
)/12.0 AS all_orgs_incl_active_years
FROM read_parquet('data/orgs.parquet');
